select * from mvprecio

select * from MTMERCIA

select m.codprecio,m.codproduc,m.unidad,c.codigo, c.UNIDADMED from mvprecio as m, MTMERCIA as c where m.CODPRODUC=c.CODIGO AND m.CODPRODUC='100664'

use colnotexsa

update MTMERCIA
set MTMERCIA.COSTO_USDR = (select COSTO_USDR from  AAAFacAGO23$
               where MTMERCIA.CODIGO =  AAAFacAGO23$.CODIGO)
where MTMERCIA.CODIGO in (select CODIGO from  AAAFacAGO23$)

---- query para actualizar unidades de medida para verona
USE VERONASAS
update MVPRECIO
set MVPRECIO.UNIDAD = (select UNIDADMED from MTMERCIA
               where MVPRECIO.CODPRODUC = MTMERCIA.CODIGO) where  MVPRECIO.CODPRECIO='01' and MVPRECIO.CODPRODUC in (select CODIGO from MTMERCIA) 

---- query para revisar si tenemos duplicado
SELECT 
    CODPRODUC, 
    COUNT(*) AS Cantidad
FROM 
    MvPrecio
GROUP BY 
    CODPRODUC
HAVING 
    COUNT(*) > 1
ORDER BY 
    Cantidad DESC;


